private static float[] readSplit(String[] split){
  float[] ret=new float[split.length];
  for (int i=0; i < split.length; i++) {
    try {
      ret[i]=Float.parseFloat(split[i]);
    } catch (NumberFormatException | NullPointerException e) {
      ret[i] = 0.0f; // 或其他默认值
    }
  }
  return ret;
}
